<?php
declare(strict_types=1);require_once __DIR__.'/common.php';$user=qa_require_user();qa_post();$id=(int)($_POST['id']??0);$pdo=db();$st=$pdo->prepare('SELECT id FROM qa_questions WHERE id=? AND user_id=?');$st->execute([$id,(int)$user['id']]);if(!$st->fetch())exit('Not allowed.');$files=$pdo->prepare('SELECT file_path FROM qa_attachments WHERE question_id=? OR answer_id IN (SELECT id FROM qa_answers WHERE question_id=?)');$files->execute([$id,$id]);foreach($files->fetchAll() as $f){$path=__DIR__.'/../../'.str_replace('dashboard/group-peer/','dashboard/group-peer/',$f['file_path']);if(is_file($path))@unlink($path);}$pdo->prepare('DELETE FROM qa_questions WHERE id=?')->execute([$id]);qa_redirect('index.php');
